sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var currentCity = g_form.getValue("city");
    var currentState = g_form.getValue("state");

    if (isLoading||!currentCity || !currentState) {
        g_form.hideFieldMsg("city", true);
        g_form.hideFieldMsg("state", true);
        return;
    }
    var ga = new GlideAjax("BaseTableUtils");
    ga.addParam("sysparm_name", "checkCityStateDupe");
    ga.addParam("sysparm_city_to_check", currentCity);
    ga.addParam("sysparm_state_to_check", currentState);

    ga.getXMLAnswer(handleCityStateResponse);
}

function handleCityStateResponse(isDuplicate) {

    if (isDuplicate === "true") {
        g_form.clearValue("city");
        g_form.showFieldMsg("city", "This City and State combination already exists and cannot be duplicated, please swap them.", "error");
        g_form.showFieldMsg("state", "This City and State combination already exists and cannot be duplicated, please swap them.", "error");
    } else {
        g_form.hideFieldMsg("city", true);
        g_form.hideFieldMsg("state", true);
    }
}
